contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bytes memory data) public {
        require(true);
        bool reverted;
        c.forward(address(this), data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted);
    }

    fallback() external payable {}
    receive() external payable {}
}

